module legacy_buffers;
fn old_read(value:i64) -> i64 { return value+1; }
fn old_write(value:str) -> str { return value; }
fn old_bytes(value:i64) -> i64 { return value; }
fn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }
server fn preserved_file_effect(path:str) -> result<str> !{fs} { return file_read_text(path); }
server fn reader() -> (server fn(str)->result<str> !{fs}) { return preserved_file_effect; }
fn main() -> unit !{io} { print(identity(old_read(41)+old_bytes(0))); print(old_write("Я🧠")); }
test fn preserved_test() -> unit { assert(old_read(41)==42); assert(old_write("text")=="text"); assert(old_bytes(7)==7); }
